"use client"
import { useState } from "react"
import { DataTable } from "@/components/blocks/data-table"
const rows = [{ id: "task-1", title: "Review changes" }]
export function SelectableTasks() {
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  return <DataTable rows={rows} caption="Tasks" getRowId={row => row.id}
    getRowLabel={row => row.title} selectedIds={selectedIds} onSelectionChange={setSelectedIds}
    columns={[{ id: "title", header: "Title", cell: row => row.title }]} />
}

